Input: {"question": "Who was the candidate selected by the Conservative Party in the Newport by-election?", "original_source_segments": {"D1S1": {"document_number": 1, "doc_id": "ramdocs-0347-aa27213d377d:d00", "start": 0, "end": 181, "text": "1945 Newport by-election The Newport by-election, 1945 was a parliamentary by-election held on 17 May 1945 for the British House of Commons constituency of Newport in Monmouthshire."}, "D1S2": {"document_number": 1, "doc_id": "ramdocs-0347-aa27213d377d:d00", "start": 182, "end": 238, "text": "It was the last by-election of the 1935-1945 Parliament."}, "D1S3": {"document_number": 1, "doc_id": "ramdocs-0347-aa27213d377d:d00", "start": 239, "end": 390, "text": "The seat had become vacant on the death of the constituency's Conservative Member of Parliament (MP), Sir Reginald Clarry, on 17 January 1945, aged 62."}, "D1S4": {"document_number": 1, "doc_id": "ramdocs-0347-aa27213d377d:d00", "start": 391, "end": 545, "text": "He had held the seat since a 1922 by-election, with a two-year gap after his defeat at the 1929 general election (he was re-elected at the 1931 election)."}, "D1S5": {"document_number": 1, "doc_id": "ramdocs-0347-aa27213d377d:d00", "start": 546, "end": 626, "text": "The Conservative Party selected as its candidate Ronald Bell, an Oxford-educated"}, "D2S1": {"document_number": 2, "doc_id": "ramdocs-0347-aa27213d377d:d01", "start": 0, "end": 30, "text": "for the 1955 general election."}, "D2S2": {"document_number": 2, "doc_id": "ramdocs-0347-aa27213d377d:d01", "start": 31, "end": 175, "text": "The Conservative Party selected as its candidate Donald Box, a stockbroker from Cardiff who had contested the seat at the 1955 general election."}, "D2S3": {"document_number": 2, "doc_id": "ramdocs-0347-aa27213d377d:d01", "start": 176, "end": 274, "text": "The Liberal Party did not field a candidate, and third candidate was Emrys Roberts of Plaid Cymru."}, "D2S4": {"document_number": 2, "doc_id": "ramdocs-0347-aa27213d377d:d01", "start": 275, "end": 368, "text": "Soskice held the seat with a majority higher than that achieved by Freeman the previous year."}, "D2S5": {"document_number": 2, "doc_id": "ramdocs-0347-aa27213d377d:d01", "start": 369, "end": 501, "text": "He held the seat until he retired from the House of Commons at the 1966 general election, having been Home Secretary from 1964–1965."}, "D2S6": {"document_number": 2, "doc_id": "ramdocs-0347-aa27213d377d:d01", "start": 502, "end": 589, "text": "Box was elected at the 1959 general election in Cardiff North, and held that seat until"}, "D3S1": {"document_number": 3, "doc_id": "ramdocs-0347-aa27213d377d:d02", "start": 0, "end": 22, "text": "in the \"Morning Post\"."}, "D3S2": {"document_number": 3, "doc_id": "ramdocs-0347-aa27213d377d:d02", "start": 23, "end": 421, "text": "His candidature was not well received by the Conservative leadership at Westminster, with Austen Chamberlain, leader of the Conservative MPs, requesting that Conservative Central Office should not aid Clarry's campaign, but crucially Clarry was still the official party nominee for the seat and it would be dangerous for any leader of the party to provoke a row by repudiating the official nominee."}, "D3S3": {"document_number": 3, "doc_id": "ramdocs-0347-aa27213d377d:d02", "start": 422, "end": 488, "text": "Lewis Haslam died on 12 September 1922 following a sudden illness."}, "D3S4": {"document_number": 3, "doc_id": "ramdocs-0347-aa27213d377d:d02", "start": 489, "end": 600, "text": "The Conservatives ran the already selected Reginald Clarry, a self-made man who had worked as a civil engineer."}, "D3S5": {"document_number": 3, "doc_id": "ramdocs-0347-aa27213d377d:d02", "start": 601, "end": 626, "text": "The Labour Party ran John"}}, "original_cards": [{"doc_id": "ramdocs-0347-aa27213d377d:d00", "card_id": "ramdocs-0347-aa27213d377d:d00:c0", "entity": "Ronald Bell", "scope": "Conservative Party candidate for the 1945 Newport by-election", "claim": "The Conservative Party selected Ronald Bell as its candidate for the 1945 Newport by-election.", "answer": "Ronald Bell", "quote": "The Conservative Party selected as its candidate Ronald Bell, an Oxford-educated", "original_document_number": 1}, {"doc_id": "ramdocs-0347-aa27213d377d:d01", "card_id": "ramdocs-0347-aa27213d377d:d01:c0", "entity": "Donald Box", "scope": "Conservative Party candidate in the Newport by-election", "claim": "The Conservative Party selected as its candidate Donald Box for the Newport by-election.", "answer": "Donald Box", "quote": "The Conservative Party selected as its candidate Donald Box, a stockbroker from Cardiff who had contested the seat at the 1955 general election.", "original_document_number": 2}, {"doc_id": "ramdocs-0347-aa27213d377d:d02", "card_id": "ramdocs-0347-aa27213d377d:d02:c0", "entity": "Reginald Clarry", "scope": "Conservative Party candidate in the Newport by-election", "claim": "The Conservatives ran the already selected Reginald Clarry as their candidate in the Newport by-election.", "answer": "Reginald Clarry", "quote": "The Conservatives ran the already selected Reginald Clarry, a self-made man who had worked as a civil engineer.", "original_document_number": 3}], "current_answers": ["Ronald Bell", "Reginald Clarry", "Donald Box"], "candidate_answers": [{"candidate_id": "R0", "answer": "Ronald Bell", "origin": "initial"}, {"candidate_id": "R1", "answer": "Reginald Clarry", "origin": "initial"}, {"candidate_id": "R2", "answer": "Donald Box", "origin": "coverage_addition"}], "requested_slot_hint": "person"}

